//! Types and pure helpers shared by native Rust tests and CLVM compilation.
//!
//! Nominal types prevent source-level domain swaps. Their public constructors
//! establish no cryptographic or protocol invariant. The CLVM ABI validates the
//! inner representation, not a runtime nominal tag or constructor predicate.
#![no_std]

#[cfg(feature = "alloc")]
extern crate alloc;

pub use chialisp_oxide_macros::puzzle;

mod domain;
pub use domain::*;

mod tree;
pub use tree::*;

mod cons;
pub use cons::Cons;

#[cfg(feature = "alloc")]
mod owned_tree;
#[cfg(feature = "alloc")]
pub use owned_tree::*;

mod hashing;
pub use hashing::{sha256, sha256_parts};

mod coin_context;
pub use coin_context::*;

mod apply;
pub use apply::{ResourceExhausted, apply};

pub mod curry;

/// Explicit CLVM byte, integer and boolean operators through the reviewed VM bridge.
pub mod raw_clvm;

mod raw_clvm_crypto;

mod raw_clvm_variadic;

//! Immutable CLVM data, with ordinary Rust lifetimes and pattern matching.
//!
//! A tree carries its original atom bytes. Numeric padding, improper pairs and
//! arbitrary tails are data; this type does not interpret or normalize them.
//! The compiler supports direct recursive traversal of this restricted shape.
//! The opt-in `alloc` feature adds `OwnedTree` for restricted owned
//! pair construction. General enums, mutable references, pointer/allocator APIs,
//! and general runtime program evaluation remain outside the supported subset.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tree<'a> {
    Atom(&'a [u8]),
    Pair(&'a Tree<'a>, &'a Tree<'a>),
}

/// CLVM's quote operator as data, for constructing a quoted program.
pub const QUOTE: Tree<'static> = Tree::Atom(&[1]);

/// Construct a program returning `value` when applied to any environment.
///
/// This is an ordinary Rust function. The compiler checks and lowers its MIR;
/// its name does not grant it intrinsic semantics.
pub fn quote<'a>(value: &'a Tree<'a>) -> Tree<'a> {
    Tree::Pair(&QUOTE, value)
}

//! Owned pair nodes with borrowed, immutable atom bytes.

use alloc::boxed::Box;

/// An ordinary Rust owned tree, preserving every atom byte and improper tail.
///
/// Native execution allocates ordinary `Box` pair nodes. CLVM compilation
/// lowers a restricted set of those operations to logical pairs; it does not
/// expose pointer or allocator APIs or make allocation and recursion free.
pub enum OwnedTree<'a> {
    Atom(&'a [u8]),
    Pair(Box<OwnedTree<'a>>, Box<OwnedTree<'a>>),
}

#![forbid(unsafe_code)]
//! Exact atom-payload hashing for native tests and the reviewed compiler bridge.
//! This module does not establish authorization, domain separation or security.

/// SHA256 of the exact bytes, returning all 32 digest bytes, including zeros.
///
/// No integer, UTF-8, hexadecimal or CLVM serialization conversion is performed.
pub fn sha256(bytes: &[u8]) -> [u8; 32] {
    sha256_parts(bytes, &[], &[])
}

/// Scalar SHA-256 of the exact concatenation a || b || c.
///
/// Native kernel for the prototype compiler bridge; not a verified implementation.
/// Byte/block positions use u128: three usize lengths plus SHA padding fit even
/// on a 64-bit target. FIPS 180-4 defines SHA-256 for messages below 2^64 bits;
/// this implementation encodes the low 64 bits of the bit length explicitly.
/// No allocation, helper/trait calls, architecture dispatch or wrapping methods.
// Keep the reviewed scalar operations explicit: rotate/div_ceil methods would
// change the closed MIR call graph that the compiler bridge matches.
#[allow(clippy::manual_rotate, clippy::manual_div_ceil)]
pub fn sha256_parts(a: &[u8], b: &[u8], c: &[u8]) -> [u8; 32] {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let a_len = a.len() as u128;
    let ab_len = a_len + b.len() as u128;
    let message_len = ab_len + c.len() as u128;
    let bit_len = (message_len << 3) as u64;
    let padded_len = ((message_len + 9 + 63) / 64) * 64;
    let mut block_start = 0u128;
    while block_start < padded_len {
        let mut w = [0u32; 64];
        let mut i = 0usize;
        while i < 64 {
            let position = block_start + i as u128;
            let byte = if position < a_len {
                a[position as usize]
            } else if position < ab_len {
                b[(position - a_len) as usize]
            } else if position < message_len {
                c[(position - ab_len) as usize]
            } else if position == message_len {
                0x80
            } else if position >= padded_len - 8 {
                (bit_len >> ((padded_len - 1 - position) as u32 * 8)) as u8
            } else {
                0
            };
            let word = i / 4;
            w[word] = (w[word] << 8) | byte as u32;
            i += 1;
        }
        i = 16;
        while i < 64 {
            let x = w[i - 15];
            let y = w[i - 2];
            let small0 = ((x >> 7) | (x << 25)) ^ ((x >> 18) | (x << 14)) ^ (x >> 3);
            let small1 = ((y >> 17) | (y << 15)) ^ ((y >> 19) | (y << 13)) ^ (y >> 10);
            w[i] = (w[i - 16] as u64 + small0 as u64 + w[i - 7] as u64 + small1 as u64) as u32;
            i += 1;
        }
        let mut aa = h[0];
        let mut bb = h[1];
        let mut cc = h[2];
        let mut dd = h[3];
        let mut ee = h[4];
        let mut ff = h[5];
        let mut gg = h[6];
        let mut hh = h[7];
        i = 0;
        while i < 64 {
            let big1 =
                ((ee >> 6) | (ee << 26)) ^ ((ee >> 11) | (ee << 21)) ^ ((ee >> 25) | (ee << 7));
            let choose = (ee & ff) ^ (!ee & gg);
            let temp1 =
                (hh as u64 + big1 as u64 + choose as u64 + K[i] as u64 + w[i] as u64) as u32;
            let big0 =
                ((aa >> 2) | (aa << 30)) ^ ((aa >> 13) | (aa << 19)) ^ ((aa >> 22) | (aa << 10));
            let majority = (aa & bb) ^ (aa & cc) ^ (bb & cc);
            let temp2 = (big0 as u64 + majority as u64) as u32;
            hh = gg;
            gg = ff;
            ff = ee;
            ee = (dd as u64 + temp1 as u64) as u32;
            dd = cc;
            cc = bb;
            bb = aa;
            aa = (temp1 as u64 + temp2 as u64) as u32;
            i += 1;
        }
        h[0] = (h[0] as u64 + aa as u64) as u32;
        h[1] = (h[1] as u64 + bb as u64) as u32;
        h[2] = (h[2] as u64 + cc as u64) as u32;
        h[3] = (h[3] as u64 + dd as u64) as u32;
        h[4] = (h[4] as u64 + ee as u64) as u32;
        h[5] = (h[5] as u64 + ff as u64) as u32;
        h[6] = (h[6] as u64 + gg as u64) as u32;
        h[7] = (h[7] as u64 + hh as u64) as u32;
        block_start += 64;
    }
    let mut digest = [0u8; 32];
    let mut i = 0usize;
    while i < 32 {
        digest[i] = (h[i / 4] >> (24 - (i % 4) * 8)) as u8;
        i += 1;
    }
    digest
}

#[cfg(test)]
mod tests {
    use super::{sha256, sha256_parts};

    #[test]
    fn known_answers_and_exact_multipart_payloads() {
        let empty = [
            0xe3, 0xb0, 0xc4, 0x42, 0x98, 0xfc, 0x1c, 0x14, 0x9a, 0xfb, 0xf4, 0xc8, 0x99, 0x6f,
            0xb9, 0x24, 0x27, 0xae, 0x41, 0xe4, 0x64, 0x9b, 0x93, 0x4c, 0xa4, 0x95, 0x99, 0x1b,
            0x78, 0x52, 0xb8, 0x55,
        ];
        let abc = [
            0xba, 0x78, 0x16, 0xbf, 0x8f, 0x01, 0xcf, 0xea, 0x41, 0x41, 0x40, 0xde, 0x5d, 0xae,
            0x22, 0x23, 0xb0, 0x03, 0x61, 0xa3, 0x96, 0x17, 0x7a, 0x9c, 0xb4, 0x10, 0xff, 0x61,
            0xf2, 0x00, 0x15, 0xad,
        ];
        assert_eq!(sha256(b""), empty);
        assert_eq!(sha256_parts(b"", b"", b""), empty);
        assert_eq!(sha256(b"abc"), abc);
        assert_eq!(sha256_parts(b"a", b"b", b"c"), abc);
        assert_eq!(sha256_parts(b"", b"abc", b""), abc);
        assert_ne!(sha256(b""), sha256(b"\0"));
        assert_ne!(sha256(b"\x01"), sha256(b"\0\x01"));
    }
}

#![forbid(unsafe_code)]
//! Dynamic application of an untrusted CLVM program to an untrusted environment.
//!
//! `apply(program, environment)` is CLVM's `a` operator as a Rust function. In a
//! compiled puzzle the reviewed compiler bridge lowers actual calls of this
//! reserved export to opcode 2 after checking its identity, exact signature and
//! implementation fingerprint; the export name grants nothing. Both operands are
//! evaluated once, in order, before the application; a failing applied program
//! fails the whole puzzle, and an unused result is still evaluated.
//!
//! Natively this crate is `no_std` and cannot evaluate CLVM. Without the `vm`
//! feature the function panics, which the compiler bridge fingerprints as the
//! reviewed body. The `vm` feature evaluates through the pinned VM so that host
//! tests and the corpus oracle can run puzzles that apply inner programs.
//! Neither route establishes termination, cost bounds, authorization or
//! compiler preservation for the applied program.
use crate::Tree;

/// Apply `program` to `environment` as CLVM's `a` operator does.
///
/// The applied program's result is an arbitrary tree. Its failure rejects the
/// caller. Host resource exhaustion in the native evaluator is a host limit,
/// reported through [`ResourceExhausted`], never a policy rejection.
#[cfg(not(feature = "vm"))]
pub fn apply<'a>(_program: &Tree<'a>, _environment: &Tree<'a>) -> Tree<'static> {
    // A bare panic lowers to one `panic` lang-item call that the compiler
    // bridge fingerprints; a message would pull in `fmt::Arguments`.
    panic!()
}

/// Apply `program` to `environment` as CLVM's `a` operator does.
///
/// Evaluates through the pinned VM in mempool mode with a fixed native cost
/// ceiling. A program failure panics (a policy rejection); exceeding the native
/// ceiling or a host allocation limit panics with a [`ResourceExhausted`]
/// payload, which oracles must report as inconclusive rather than rejection.
#[cfg(feature = "vm")]
pub fn apply<'a>(program: &Tree<'a>, environment: &Tree<'a>) -> Tree<'static> {
    vm::apply(program, environment)
}

/// Host resource exhaustion inside the native evaluator; not a policy result.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResourceExhausted {
    /// The native cost ceiling or host allocation bound that was exceeded.
    pub limit: u64,
}

#[cfg(feature = "vm")]
mod vm {
    extern crate std;
    use super::ResourceExhausted;
    use crate::Tree;
    use chialisp_oxide_vm::classify_failure;
    use clvmr::{Allocator, ChiaDialect, MEMPOOL_MODE, NodePtr, allocator::SExp, run_program};
    use std::boxed::Box;
    use std::vec::Vec;

    /// Fixed native evaluation ceiling. The VM charges the applied program
    /// against the outer puzzle's budget; a native oracle has no such budget,
    /// so this is deliberately generous and its exhaustion is inconclusive.
    pub const NATIVE_MAX_COST: u64 = 10_000_000_000;
    /// Bound on nodes materialized for inputs and the result.
    pub const MAX_NODES: usize = 4_000_000;

    fn exhausted(limit: u64) -> ! {
        std::panic::panic_any(ResourceExhausted { limit })
    }

    fn encode(a: &mut Allocator, tree: &Tree<'_>, budget: &mut usize) -> NodePtr {
        // Iterative post-order encoding; deep right spines are ordinary data.
        enum Step<'t, 'a> {
            Visit(&'t Tree<'a>),
            Pair,
        }
        let mut steps = Vec::new();
        let mut values: Vec<NodePtr> = Vec::new();
        steps.push(Step::Visit(tree));
        while let Some(step) = steps.pop() {
            match step {
                Step::Visit(Tree::Atom(bytes)) => {
                    *budget = budget
                        .checked_sub(1)
                        .unwrap_or_else(|| exhausted(MAX_NODES as u64));
                    values.push(
                        a.new_atom(bytes)
                            .unwrap_or_else(|_| exhausted(MAX_NODES as u64)),
                    );
                }
                Step::Visit(Tree::Pair(first, rest)) => {
                    *budget = budget
                        .checked_sub(1)
                        .unwrap_or_else(|| exhausted(MAX_NODES as u64));
                    steps.push(Step::Pair);
                    steps.push(Step::Visit(rest));
                    steps.push(Step::Visit(first));
                }
                Step::Pair => {
                    let rest = values.pop().expect("pair rest");
                    let first = values.pop().expect("pair first");
                    values.push(
                        a.new_pair(first, rest)
                            .unwrap_or_else(|_| exhausted(MAX_NODES as u64)),
                    );
                }
            }
        }
        values.pop().expect("encoded root")
    }

    fn decode(a: &Allocator, node: NodePtr, budget: &mut usize) -> Tree<'static> {
        // Iterative decoding into leaked boxes: the result must outlive its
        // inputs, and this evaluator exists only for host tests and oracles.
        enum Step {
            Visit(NodePtr),
            Pair,
        }
        let mut steps = Vec::new();
        let mut values: Vec<Tree<'static>> = Vec::new();
        steps.push(Step::Visit(node));
        while let Some(step) = steps.pop() {
            match step {
                Step::Visit(node) => {
                    *budget = budget
                        .checked_sub(1)
                        .unwrap_or_else(|| exhausted(MAX_NODES as u64));
                    match a.sexp(node) {
                        SExp::Atom => {
                            let bytes: &'static [u8] =
                                Box::leak(a.atom(node).as_ref().to_vec().into_boxed_slice());
                            values.push(Tree::Atom(bytes));
                        }
                        SExp::Pair(first, rest) => {
                            steps.push(Step::Pair);
                            steps.push(Step::Visit(rest));
                            steps.push(Step::Visit(first));
                        }
                    }
                }
                Step::Pair => {
                    let rest = values.pop().expect("pair rest");
                    let first = values.pop().expect("pair first");
                    let first: &'static Tree<'static> = Box::leak(Box::new(first));
                    let rest: &'static Tree<'static> = Box::leak(Box::new(rest));
                    values.push(Tree::Pair(first, rest));
                }
            }
        }
        values.pop().expect("decoded root")
    }

    pub fn apply<'a>(program: &Tree<'a>, environment: &Tree<'a>) -> Tree<'static> {
        let mut a = Allocator::new();
        let mut budget = MAX_NODES;
        let program = encode(&mut a, program, &mut budget);
        let environment = encode(&mut a, environment, &mut budget);
        match run_program(
            &mut a,
            &ChiaDialect::new(MEMPOOL_MODE),
            program,
            environment,
            NATIVE_MAX_COST,
        ) {
            Ok(reduction) => decode(&a, reduction.1, &mut budget),
            Err(error) => {
                let failure = classify_failure(&error);
                if failure.is_program_rejection() {
                    panic!("applied CLVM program rejected: {error:?}")
                }
                exhausted(NATIVE_MAX_COST)
            }
        }
    }
}

//! Explicit raw CLVM operators, constructed as ordinary Rust tree data.
//!
//! These helpers call the reviewed [`crate::apply`] bridge. The compiler lowers
//! their real Rust bodies; their names grant no intrinsic behavior. Arguments
//! and results have CLVM tree/atom semantics, not Rust slice or integer semantics.
//! For example, division rounds toward negative infinity and accepts integer
//! atoms outside Rust's fixed widths. Byte operations preserve exact atom bytes.
//!
//! Native calls require the facade's `vm` feature and execute through its pinned
//! VM oracle. Without it they reach `apply`'s panic body. That evaluator leaks
//! returned tree storage for host tests; it is not an allocation-free native
//! byte API. Applied failures propagate, resource failures remain inconclusive,
//! and no proof model admits these calls. Dialect/activation rules still apply.
use crate::{Tree, apply};

// Fixed active crypto operators share this explicit CLVM interface.
pub use crate::raw_clvm_crypto::*;
pub use crate::raw_clvm_variadic::*;

/// Return the atom byte length as a CLVM integer atom; a pair rejects.
pub fn byte_length<'a>(value: &'a Tree<'a>) -> Tree<'static> {
    let nil = Tree::Atom(&[]);
    let path0 = Tree::Atom(&[1]);
    let args0 = Tree::Pair(&path0, &nil);
    let opcode = Tree::Atom(&[13]);
    let program = Tree::Pair(&opcode, &args0);
    apply(&program, value)
}

/// Return the end-exclusive atom substring under CLVM's index rules.
/// `start` and `end` are raw integer atoms; this is not Rust slice indexing.
pub fn byte_substr<'a>(
    value: &'a Tree<'a>,
    start: &'a Tree<'a>,
    end: &'a Tree<'a>,
) -> Tree<'static> {
    let nil = Tree::Atom(&[]);
    let path0 = Tree::Atom(&[2]);
    let path1 = Tree::Atom(&[5]);
    let path2 = Tree::Atom(&[11]);
    let args2 = Tree::Pair(&path2, &nil);
    let args1 = Tree::Pair(&path1, &args2);
    let args0 = Tree::Pair(&path0, &args1);
    let opcode = Tree::Atom(&[12]);
    let program = Tree::Pair(&opcode, &args0);
    let last = Tree::Pair(end, &nil);
    let rest = Tree::Pair(start, &last);
    let environment = Tree::Pair(value, &rest);
    apply(&program, &environment)
}

/// Concatenate two atom payloads exactly; either pair argument rejects.
pub fn byte_concat<'a>(left: &'a Tree<'a>, right: &'a Tree<'a>) -> Tree<'static> {
    let nil = Tree::Atom(&[]);
    let path0 = Tree::Atom(&[2]);
    let path1 = Tree::Atom(&[3]);
